// Helper function to count occurrences of a character in a string
function count(s: string, c: char): int
{
    var count := 0;
    var i := 0;
    while i < s.Length
        invariant 0 <= i <= s.Length
        invariant count == CountChars(s, c, i)
    {
        if s[i] == c {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

// Helper function to count characters in the string up to a certain index
function CountChars(s: string, c: char, upTo: int): int
{
    var count := 0;
    var i := 0;
    while i < upTo
        invariant 0 <= i <= upTo
        invariant count == CountChars(s, c, i)
    {
        if s[i] == c {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

